:root {
  --bg: #1a1a2e;
  --surface: #16213e;
  --primary: #e94560;
  --accent: #0f3460;
  --text: #eaeaea;
  --card-back: #533483;
  --card-front: #e94560;
  --matched: #4e9f3d;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.game-container {
  width: 100%;
  max-width: 480px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  align-items: center;
}

.game-header {
  text-align: center;
  width: 100%;
}

h1 {
  font-size: clamp(1.5rem, 5vw, 2rem);
  margin-bottom: 8px;
  color: var(--primary);
}

.stats {
  display: flex;
  justify-content: center;
  gap: 24px;
  font-size: 1.125rem;
  font-weight: 600;
}

.game-board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  width: 100%;
  aspect-ratio: 1 / 1;
  max-width: 440px;
}

.card {
  position: relative;
  background: var(--card-back);
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: transform 0.2s, background 0.2s, box-shadow 0.2s;
  font-size: 0;
  color: transparent;
  aspect-ratio: 1 / 1;
  width: 100%;
  padding: 0;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
}

.card:hover:not(.matched):not(.flipped) {
  transform: scale(1.05);
  box-shadow: 0 6px 12px rgba(0, 0, 0, 0.4);
}

.card:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 3px;
}

.card.flipped,
.card.matched {
  background: var(--card-front);
  transform: rotateY(180deg);
}

.card.matched {
  background: var(--matched);
  cursor: default;
}

.card.matched:hover {
  transform: rotateY(180deg);
}

.win-message {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary);
  text-align: center;
}

.win-message.hidden {
  display: none;
}

.btn {
  padding: 14px 32px;
  font-size: 1.125rem;
  font-weight: 600;
  font-family: var(--font);
  background: var(--primary);
  color: #fff;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
}

.btn:hover {
  background: #c73a52;
}

.btn:active {
  transform: scale(0.97);
}

.btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 3px;
}

@media (max-width: 400px) {
  .game-board {
    gap: 8px;
  }
  .card {
    border-radius: 8px;
  }
  .stats {
    font-size: 1rem;
    gap: 16px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .card, .btn {
    transition: none;
  }
  .card:hover:not(.matched):not(.flipped) {
    transform: none;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
  }
}

(function () {
  'use strict';

  const PAIRS = 8;
  const COLORS = [
    '#e94560', '#0f3460', '#533483', '#4e9f3d',
    '#f2a541', '#3a86ff', '#ff006e', '#8338ec'
  ];

  const boardEl = document.getElementById('game-board');
  const movesEl = document.getElementById('moves');
  const pairsEl = document.getElementById('pairs');
  const winEl = document.getElementById('win-message');
  const newGameBtn = document.getElementById('new-game');

  let deck = [];
  let flipped = [];
  let matched = 0;
  let moves = 0;
  let lock = false;

  function shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  }

  function createDeck() {
    const cards = [];
    for (let i = 0; i < PAIRS; i++) {
      cards.push({ color: COLORS[i], id: i });
      cards.push({ color: COLORS[i], id: i });
    }
    return shuffle(cards);
  }

  function renderBoard() {
    boardEl.innerHTML = '';
    deck.forEach((card, index) => {
      const btn = document.createElement('button');
      btn.className = 'card';
      btn.type = 'button';
      btn.dataset.index = index;
      btn.dataset.color = card.color;
      btn.setAttribute('aria-label', 'Card ' + (index + 1) + ', hidden');
      btn.addEventListener('click', onCardClick);
      boardEl.appendChild(btn);
    });
  }

  function onCardClick(e) {
    const card = e.currentTarget;
    if (lock || card.classList.contains('flipped') || card.classList.contains('matched')) return;

    card.classList.add('flipped');
    card.style.background = card.dataset.color;
    card.setAttribute('aria-label', 'Card ' + (parseInt(card.dataset.index, 10) + 1) + ', revealed');
    flipped.push(card);

    if (flipped.length === 2) {
      moves++;
      movesEl.textContent = 'Moves: ' + moves;
      checkMatch();
    }
  }

  function checkMatch() {
    lock = true;
    const [a, b] = flipped;
    if (a.dataset.color === b.dataset.color) {
      a.classList.add('matched');
      b.classList.add('matched');
      a.setAttribute('aria-label', 'Card ' + (parseInt(a.dataset.index, 10) + 1) + ', matched');
      b.setAttribute('aria-label', 'Card ' + (parseInt(b.dataset.index, 10) + 1) + ', matched');
      matched++;
      pairsEl.textContent = 'Pairs: ' + matched + '/' + PAIRS;
      flipped = [];
      lock = false;
      if (matched === PAIRS) {
        winEl.classList.remove('hidden');
        winEl.textContent = 'You won in ' + moves + ' moves! 🎉';
        boardEl.setAttribute('aria-hidden', 'true');
      }
    } else {
      setTimeout(() => {
        a.classList.remove('flipped');
        b.classList.remove('flipped');
        a.style.background = '';
        b.style.background = '';
        a.setAttribute('aria-label', 'Card ' + (parseInt(a.dataset.index, 10) + 1) + ', hidden');
        b.setAttribute('aria-label', 'Card ' + (parseInt(b.dataset.index, 10) + 1) + ', hidden');
        flipped = [];
        lock = false;
      }, 800);
    }
  }

  function newGame() {
    deck = createDeck();
    flipped = [];
    matched = 0;
    moves = 0;
    lock = false;
    movesEl.textContent = 'Moves: 0';
    pairsEl.textContent = 'Pairs: 0/' + PAIRS;
    winEl.classList.add('hidden');
    winEl.textContent = '';
    boardEl.removeAttribute('aria-hidden');
    boardEl.style.transform = 'scale(0.95)';
    void boardEl.offsetWidth; // force reflow to ensure style change is detected
    boardEl.style.transform = '';
    renderBoard();
  }

  newGameBtn.addEventListener('click', newGame);

  newGame();
})();
